 Tap Confirm to go to [c][C74848]Love Supply[-][/c]]=],
  nostalgia_inventory_content_1 = "During your absence, to protect the beautiful world you envisioned, he made lots of efforts. But just like the wound at his abdomen, he never showed it to you. He said that phrase to alleviate your worries, and to promise you: Behind me is the safest place you can be. \\n Instead of words, he seems to prefer action to express his affection to you. In the past year, you shared %s calls, %s text messages. Even with a busy schedule, he still found time to have %s dates with you, though he still wants more. \\n He commented on your Moments %s times. Your optimism, strength, pureness, kindness and cute quirks all make him want to protect and appreciate you more. \\n You have also gained new understanding of him in the past year with him...",
  nostalgia_inventory_content_2 = "Since you appeared, he has found that his sense and sensibility are not conflicting any more. He acknowledges that you have left a permanent mark on his life. It's like when he whispers to you in the quiet night: You have made me understand the fears of a normal person.\\n This year, you texted each other %s times, made %s phone calls. You travelled together and carved %s good memories in your heart. He has opened up his innermost secrets to you. \\n He rarely checks Moments, but he hasn't missed the ones you post. He has commented on your posts a total of %s times this year. For him, the time he shared with you was brighter than the aurora. \\n You've noticed something different about him in the past year by his side...",
  nostalgia_inventory_content_3 = "Along the way, he has carried too much weight. The darkest moment of his life was when you disappeared. But even though there is little hope, he never wanted to give up his faith or you. When you meet again, he can finally relax, smile and say to you: As long as you’re around, I always have sweet dreams. \\n This year, you texted each other %s times, made %s phone calls, rode on the wind together %s times. Before you know it, you have become his solid support. \\n Though sometimes he will feel tired, but whenever he sees news about you, his face will light up with a gentle smile. He has commented on your Moments this year %s times. Your presence is like a breeze, dispelling the clouds from his mind. \\n In the last year, you seem to have discovered new shining points in him...",
  nostalgia_inventory_content_4 = "He has finally revealed to you the other side of himself that he keeps hidden. In endless darkness, he silently suffered unimaginable pain, only wishing to show you smiles like sunshine. In front of the exploding ferris wheel, with mixed feelings, he smiled and asked you: Will you come with me? \\n You shared %s calls, %s text messages, had %s adventures together. No matter when, you are always his best partner. \\n Even though he has a lot responsibilities, he will often comment on your Moments. Over the course of the year, he commented %s times. Your messages are the only light in the long night he watches over alone. \\n In the time you've shared this year, he's shown you a side you've never seen before...",
