  battle_prepare_s2_panel_start = "Start promoting",
  previously_panel_lbltitle = "Review",
  previously_on_5101 = "As Black Swan's plot unfolded, your Evol gradually awakened as the Queen. After recalling the orphanage incident 17 years ago, you made up your mind to fight against the BS and find out the truth. \n \n As twists and turns continued on your journey, deep bonds between you and others were also established. \n \n You discovered another identity of Lucien as Ares, a key member of BS, so you decided to break with him, only to realize his true feelings in the ensuing crises – you learned about his pains and struggles while knowing that he never gave up on his quest for human evolution. \n \n You joined hands with Gavin fighting for this world, regardless of all the difficulties and dangers. While witnessing Gavin’s faith that never changed or waned, you yourself also grew strong enough to stand beside him and fight with him. \n \n You came to see the dark side of Kiro – Helios, but whether bright or dark, he was always holding onto light in the dark, and his mask gradually came off in front of you. He was and would always be your superhero. You were grateful for Victor, who had been by your side all the time. He has taught you to become stronger and to handle crises on your own. He also paid huge prices himself, travelling through time and space, just to stay with you and see you awakening as the Queen. \n \n You also met a mysterious guy – Shaw, who broke into your world like a thunderbolt, whether you accepted it or not. His presence infused excitement and fun into your life. He opened your eyes to a different world. \n \n You’ve been with these men through out-of-control Evol, the flu, Pure White Winter... \n \n You’ve come to realize that Black Swan was not the real enemy, and you’ve also traveled through time to learn the truth about the world. All karma pointed to the cycle of life, and in this evolution of civilization, as the Black Swan Queen, what role you were playing? What kind of choices you were supposed to make? \n \n In this process, you gradually found yourself and stepped toward your place as the Black Swan Queen. After all the events came to an end, Evolvers and ordinary people were learning to live in harmony. As you thought the dust had settled, Loveland City was once again struck by a series of natural catastrophes, all of which were signs that Apocalypse was approaching!",
